const rows = $json.data?.list || [];
const totals = { spend: 0, impressions: 0, clicks: 0, conversions: 0, real_result: 0 };
const campaigns = [];

for (const r of rows) {
  const d = r.dimensions || {};
  const m = r.metrics || {};
  const spend = Number(m.spend || 0);
  const impressions = Number(m.impressions || 0);
  const clicks = Number(m.clicks || 0);
  const conversions = Number(m.conversions || 0);
  const realResult = Number(m.real_result || 0);

  totals.spend += spend;
  totals.impressions += impressions;
  totals.clicks += clicks;
  totals.conversions += conversions;
  totals.real_result += realResult;

  campaigns.push({
    campaign_id: d.campaign_id,
    date: d.stat_time_day,
    spend: +spend.toFixed(2),
    impressions,
    clicks,
    ctr: m.ctr ? Number(m.ctr) : (impressions > 0 ? +(clicks / impressions * 100).toFixed(2) : 0),
    cpc: m.cpc ? Number(m.cpc) : (clicks > 0 ? +(spend / clicks).toFixed(2) : 0),
    cpm: impressions > 0 ? +((spend / impressions) * 1000).toFixed(2) : 0,
    conversions,
    cost_per_conversion: conversions > 0 ? +(spend / conversions).toFixed(2) : 0,
    conversion_rate: m.conversion_rate ? Number(m.conversion_rate) : (clicks > 0 ? +(conversions / clicks * 100).toFixed(2) : 0),
    roas: realResult > 0 ? +(realResult / spend).toFixed(2) : 0,
    real_result: realResult
  });
}

const totalCtr = totals.impressions > 0 ? +(totals.clicks / totals.impressions * 100).toFixed(2) : 0;
const totalCpc = totals.clicks > 0 ? +(totals.spend / totals.clicks).toFixed(2) : 0;
const totalCvr = totals.clicks > 0 ? +(totals.conversions / totals.clicks * 100).toFixed(2) : 0;
const overallRoas = totals.spend > 0 ? +(totals.real_result / totals.spend).toFixed(2) : 0;
const totalCpi = totals.conversions > 0 ? +(totals.spend / totals.conversions).toFixed(2) : 0;

return {
  json: {
    client_name: $('Set Client Config').first().json.client_name,
    advertiser_id: $('Set Client Config').first().json.advertiser_id,
    start_date: $json.start_date,
    end_date: $json.end_date,
    request_timestamp: $json.request_timestamp,
    campaign_count: campaigns.length,
    summary: {
      total_spend: +totals.spend.toFixed(2),
      total_impressions: totals.impressions,
      total_clicks: totals.clicks,
      total_conversions: totals.conversions,
      total_real_result: totals.real_result,
      avg_ctr: totalCtr,
      avg_cpc: totalCpc,
      avg_conversion_rate: totalCvr,
      avg_cpi: totalCpi,
      overall_roas: overallRoas
    },
    campaigns,
    data_quality: {
      has_data: campaigns.length > 0,
      missing_metrics: []
    }
  }
};

